class SwiperManager{constructor(selector="[data-swiper]"){this.defaultOptions={};this.counterSelector="swiper-counter";this.selector=selector;this.instances=new Map;this.init();this.attachResizeHandler()}init(){const sliders=document.querySelectorAll(this.selector);sliders.forEach((el,index)=>{const key=el.dataset.swiperId||index;const breakpoint=el.dataset.swiperBreakpoint;const shouldInit=this._checkBreakpoint(breakpoint);const alreadyInit=this.instances.has(key);const pagination=el.querySelector(".swiper-pagination");const navigation={prev:el.querySelector(".swiper-button-prev"),next:el.querySelector(".swiper-button-next")};if(shouldInit){if(!alreadyInit){const dataOptions=this._parseOptions(el.dataset.swiperOptions);const options=this._prepareOptionsBySliderId(key,dataOptions);const swiper=new Swiper(el,options);this.instances.set(key,swiper);if(pagination)pagination.style.display="";if(navigation.prev)navigation.prev.style.display="";if(navigation.next)navigation.next.style.display=""}}else{if(alreadyInit){this.instances.get(key).destroy(true,true);this.instances.delete(key)}if(pagination)pagination.style.display="none";if(navigation.prev)navigation.prev.style.display="none";if(navigation.next)navigation.next.style.display="none"}})}_prepareOptionsBySliderId(id,options){switch(id){case"advantages-counter":return{...options,on:{init:swiper=>{this._updateCounter(swiper)},slideChange:swiper=>{this._updateCounter(swiper)}}};default:return options}}_updateCounter(slider){const counter=slider.el.querySelector(`.${this.counterSelector}`);if(counter!==null){const current=slider.realIndex+1;const total=slider.slides.length;counter.innerHTML=`<span>0${current}</span>/<span>0${total}</span>`}}_checkBreakpoint(breakpoint){if(!breakpoint)return true;return window.matchMedia(`(max-width: ${breakpoint}px)`).matches}_parseOptions(attr){try{return JSON.parse(attr||"{}")}catch(e){console.warn("Invalid Swiper options JSON:",attr);return{}}}_debounce(func,delay=200){let timer;return(...args)=>{clearTimeout(timer);timer=setTimeout(()=>func.apply(this,args),delay)}}attachResizeHandler(){window.addEventListener("resize",this._debounce(this.init))}}